const toCents = (price) => Math.round(Number(price) * 100); // "4.99" -> 499
const total = toCents("0.10") + toCents("0.20");               // 30, exactly

function formatCents(cents) {
  const dollars = Math.floor(cents / 100);
  const rest = String(cents % 100).padStart(2, "0");
  return `$${dollars}.${rest}`;
}
formatCents(1205); // "$12.05"

